package org.example;

import java.io.File;
import java.io.RandomAccessFile;
import java.util.List;
import java.util.concurrent.CompletableFuture;

import org.apache.commons.compress.utils.Lists;

import com.kuaishou.framework.util.ObjectMapperUtils;

import lombok.Data;
import lombok.extern.slf4j.Slf4j;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;


@SuppressWarnings("all")
@Slf4j
public class ChunkUploadTest {
    static final OkHttpClient CLIENT = new OkHttpClient().newBuilder()
            .build();

    public static void main(String[] args) throws Exception {

        File file = new File("你的文件地址.mp4");
      	// 1.分片上传
        int fragmentCount = chunkUpload(endpoint, uploadToken, file);
        // 2.合成分片
        finishChunkUpload(endpoint, uploadToken, fragmentCount);
    }


    /**
     *  分片上传
     */
    public static void chunkUpload(String endpoint, String uploadToken, File file) throws Exception {
        RandomAccessFile raf = new RandomAccessFile(file, "r");
        long size = file.length();
        long fragmentSize = 1024 * 1024 * 5;
        int i = 0;
        List<CompletableFuture<Void>> futures = Lists.newArrayList();
        for (; i < size / (double) fragmentSize; i++) {
            long start = fragmentSize * i;
            long end = Math.min(start + fragmentSize - 1, size - 1);
            log.info("i = {}, start = {}, end = {}", i, start, end);
            // 定位到开始位置
            raf.seek(start);
            // 读取字节数据
            byte[] buffer = new byte[(int) (end - start + 1)];
            int bytesRead = raf.read(buffer);
            int current = i;
            // 此处并发
            CompletableFuture<Void> completableFuture = CompletableFuture.runAsync(() -> {
                fragmentUpload(endpoint, uploadToken, buffer, current);
            });
            futures.add(completableFuture);
        }
        CompletableFuture.allOf(futures.toArray(new CompletableFuture[] {})).join();
    		return i;

    }

    /**
     * 单个分片上传
     */
    private static void fragmentUpload(String endpoint, String uploadToken, byte[] buffer, int fragmentId) {
        try {
            String url = String.format("https://%s/api/upload/fragment?fragment_id=%s&upload_token=%s",
                                       endpoint, fragmentId, uploadToken);
            MediaType mediaType = MediaType.parse("video/mp4");
            RequestBody body = RequestBody.create(mediaType, buffer);
            Request request = new Request.Builder()
                    .url(url)
                    .method("POST", body)
                    .addHeader("Content-Type", "video/mp4")
                    // .addHeader("User-Agent", "Your User-Agent String")   如果是Python语言Headers需要添加User-Agent
                    .build();
