        } catch (Exception e) {
            log.error("fragmentUpload error, fragment = {}, uploadToken = {}", fragment, uploadToken);
        }
    }

    /**
     * 完成分片上传
     */
    public static void finishChunkUpload(String endpoint, String uploadToken, int fragmentCount) throws Exception {
        String url = String.format("https://%s/api/upload/complete?fragment_count=%s&upload_token=%s",
                                   endpoint, fragmentCount, uploadToken);
        MediaType mediaType = MediaType.parse("text/plain");
        RequestBody body = RequestBody.create(mediaType, "");
        Request request = new Request.Builder()
                .url(url)
                .method("POST", body)
                // .addHeader("User-Agent", "Your User-Agent String") 如果是Python语言Headers需要添加User-Agent
                .build();
        Response response = CLIENT.newCall(request).execute();
        log.info("finishChunkUpload code = {}, response = {}", response.code(), response.body().string());
    }
}
